"""Serialize the legacy definition; ICU is only needed for validate.py."""
import json
from pathlib import Path
import yaml

root = Path(__file__).resolve().parent.parent
legacy = json.loads((root / ".build/nushell-legacy-build.json").read_text(encoding="utf-8"))
header = """# Nushell syntax for CotEditor.
# Generated by scripts/build.mjs; edit the generator, not this file.
# Adapted from https://github.com/hustcer/nu-grammar and
# https://github.com/nushell/vscode-nushell-lang.
# Full upstream MIT license and pinned commits are included in metadata.
# CotEditor 7 users should prefer the accompanying native .cotsyntax package.
"""
(root / "Nushell.yml").write_text(
    header + yaml.safe_dump(legacy, sort_keys=False, allow_unicode=True, width=110),
    encoding="utf-8",
)
print("Built Nushell.yml.")
